'use strict';
const E=Model.escape, money=Model.money, date=Model.date;
let D=null;
function dateTime(value){
 const text=String(value||''),zone=D?.settings?.find(x=>x.id==='workspace')?.timezone;
 if(!zone||!/[zZ]$|[+-]\d{2}:?\d{2}$/.test(text))return Model.dateTime(value);
 const instant=new Date(text);if(Number.isNaN(instant.getTime()))return '—';
 try{return instant.toLocaleString('en-US',{timeZone:zone,year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'});}catch{return Model.dateTime(value);}
}
let lastDatabaseVersion=null, refreshInFlight=false, mutationRevision=0;
const dirtyForms=new WeakSet();
const S={page:'candidates',category:'All candidates',filters:{},sort:'name',dir:1,pageNo:1,pageSize:20,selected:new Set(),profile:null,profileTab:'Production',period:'LTM',returnPage:'candidates',reviewIds:[],listScroll:0,taskBucket:'All open',taskQ:'',activityKind:'All',watchlist:null,insights:false,settingsTab:'Workspace',menu:null,custom:{},comparison:'Similar agents'};
const categories=['All candidates','Recent Co-Broker','Ready to Move','Decreasing Sales','Trouble at Current Office'];
const categoryText={'All candidates':'A focused starting point for your next conversation.','Recent Co-Broker':'Agents with a recent connection to your office.','Ready to Move':'High move potential with no active or pending deals.','Decreasing Sales':'Agents whose sample production has declined.','Trouble at Current Office':'Agents at offices with a sample decline in business or agent count.'};
const columnNames={office:'Office',volume:'Sales volume',city:'Most transacted city',move:'Potential to move',status:'CRM status',lastInteraction:'Last interaction',years:'Est. time in industry',units:'Units',change:'Volume change',active:'Active listings',pending:'Pending listings',email:'Email',phone:'Phone',viewedAt:'Last viewed',source:'Source'};
const directRailPages={research:'market',performance:'performance',workflows:'workflows',sequences:'sequences'};
const availableColumnNames=()=>D?.mode==='mixed'?{...columnNames,...CSVImportUI.tableFields(D.customFields||[])}:columnNames;
const currentAgent=()=>D.agents.find(a=>a.id===S.profile);
function linkedinProfileURL(value){
 if(!value)return null;
 try{const url=new URL(String(value).trim());const host=url.hostname.toLowerCase();return url.protocol==='https:'&&(host==='linkedin.com'||host==='www.linkedin.com')&&/^\/in\/[^/]+\/?$/i.test(url.pathname)?url.href:null;}catch{return null;}
}
function contactInfoLine(label,iconName,value,href=null){
 const shown=value||'Not added';
 return `<div class="contact-line"><span class="contact-line-icon">${icon(iconName,16)}</span><span class="contact-line-copy"><span class="contact-line-label">${E(label)}</span>${href?`<a class="contact-line-value" href="${E(href)}">${E(shown)}</a>`:`<span class="contact-line-value" title="${E(shown)}">${E(shown)}</span>`}</span></div>`;
}
function linkedinContactInfo(agent){const url=linkedinProfileURL(agent.linkedinUrl);return contactInfoLine('LinkedIn','linkedin',url?'Open profile':'Not added',url);}
function emailCompanyReviewInfo(agent){const review=agent.emailCompanyReview;return ['needs_review','unverified'].includes(review?.state)?`<p class="contact-review-alert" role="note">Email and brokerage need review. ${E(review.message||'Check the current brokerage and email before outreach.')}</p>`:'';}
const prefs=()=>D.settings.find(s=>s.id==='preferences');
const workspace=()=>D.settings.find(s=>s.id==='workspace')||{};
const needsOnboarding=()=>workspace().onboardingRequired===true||!String(workspace().name||'').trim();
const pilotHiddenPages=new Set(['market','offices','workflows','sequences']);
let recoveryState=null,recoveryError='',historyAuditState=null,historyAuditError='';
const btn=(label,action,ic='',extra='',style='')=>`<button type="button" class="button ${style}" data-action="${action}" ${extra}>${ic?icon(ic,16):''}${E(label)}</button>`;
const ib=(label,action,ic,extra='',cls='')=>`<button type="button" class="icon-button ${cls}" aria-label="${E(label)}" title="${E(label)}" data-action="${action}" ${extra}>${icon(ic,17)}</button>`;
const badge=(text)=>`<span class="badge ${String(text).toLowerCase()}">${E(text)}</span>`;
const avatar=(a,size='')=>`<span class="avatar ${size} palette-${(D.agents.indexOf(a)+6)%6}">${E(Model.initials(a.name))}</span>`;
const selectOptions=(items,value,blank)=>`${blank!==undefined?`<option value="">${E(blank)}</option>`:''}${items.map(v=>`<option ${v===value?'selected':''} value="${E(v)}">${E(v)}</option>`).join('')}`;
const empty=(title,body,ic='search',action='')=>`<div class="empty">${icon(ic,34)}<h2>${E(title)}</h2><p>${E(body)}</p>${action}</div>`;
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('toast-visible'),3200);}
async function native(action,payload={}){if(!window.webkit?.messageHandlers?.sprout)throw Error('Open Sprout Recruit.app to use this local workspace.');return await window.webkit.messageHandlers.sprout.postMessage({action,payload});}
async function mutate(action,payload,message){mutationRevision++;D=await native(action,payload);if(message)toast(message);render();}
function hasPendingEdits(){
 if(document.getElementById('overlay')?.children.length)return true;
 if([...document.querySelectorAll('form')].some(form=>dirtyForms.has(form)))return true;
 const active=document.activeElement;
 return !!(active?.isContentEditable||active?.matches('input,textarea,select'));
}
async function refreshLocalChanges(){
 if(!D||refreshInFlight||document.hidden)return;
 refreshInFlight=true;
 try{
  const {dataVersion}=await native('workspace.version');
  if(dataVersion===lastDatabaseVersion||hasPendingEdits())return;
  const revision=mutationRevision, workspace=document.getElementById('workspace'), scroll=workspace.scrollTop;
  const fresh=await native('snapshot');
  if(revision!==mutationRevision||hasPendingEdits())return;
  D=fresh;lastDatabaseVersion=dataVersion;
  S.selected=new Set([...S.selected].filter(id=>D.agents.some(a=>a.id===id)));
  if(S.profile&&!D.agents.some(a=>a.id===S.profile))S.profile=null;
  render();workspace.scrollTop=scroll;
 }catch(error){console.warn('Could not refresh local changes:',error);}
 finally{refreshInFlight=false;}
}
function pageHeader(title,sub,actions=''){return `<div class="page-head between"><div><h1>${E(title)}</h1>${sub?`<p class="sub">${E(sub)}</p>`:''}</div><div class="row">${actions}</div></div>`;}
function pageTabs(items,selected,action){return `<div class="tabs">${items.map(x=>{const label=typeof x==='string'?x:x.label;return `<button class="tab ${label===selected?'active':''}" data-action="${action}" data-value="${E(label)}">${E(label)}${typeof x==='object'?`<span class="tab-count">${x.count}</span>`:''}</button>`;}).join('')}</div>`;}
function shell(){
 document.getElementById('app').innerHTML=`<header class="topbar"><button class="logo-button" aria-label="Sprout home" data-action="navigate" data-page="dashboard">${icon('leaf',27)}</button><span class="top-word">sprout<span style="color:#8fa496;font-weight:400"> / recruit</span></span><button class="global-search" data-action="global-search">${icon('search',17)}<span>Search your workspace</span><kbd>⌘ K</kbd></button><span class="grow"></span><span class="local-pill"><span class="dot"></span>On this Mac</span><span class="sample-tag">SAMPLE WORKSPACE</span><button class="icon-button task-icon" aria-label="Tasks" data-action="navigate" data-page="tasks">${icon('task')}<span class="count-dot" id="task-count"></span></button>${ib('Notifications','notifications','bell')}<button class="avatar" aria-label="Workspace settings" data-action="navigate" data-page="settings">${E(Model.initials(workspace().name||'Recruiter'))}</button></header><nav class="rail" aria-label="Main navigation">${[['overview','home','Overview'],['recruit','target','Recruit'],['search','search','Search'],['performance','chart','Performance']].map(([id,ic,label])=>`<button class="rail-button" data-section="${id}" data-action="${directRailPages[id]?'navigate':'menu'}" data-value="${directRailPages[id]?'':id}" data-page="${directRailPages[id]||''}" title="${label}" aria-label="${label}">${icon(ic,19)}<span>${label}</span></button>`).join('')}<span class="rail-bottom"></span><button class="rail-button" data-section="settings" data-action="navigate" data-page="settings" aria-label="Settings">${icon('settings',20)}</button></nav><main id="workspace" class="workspace"></main><div id="menu-root"></div>`;
}
function navigate(page){if(pilotHiddenPages.has(page)){toast('This feature is outside the internal pilot.');return;}S.profile=null;S.page=page;S.pageNo=1;S.selected.clear();S.menu=null;render();document.getElementById('workspace').scrollTop=0;}
function render(){if(!D)return;if(needsOnboarding()){document.getElementById('workspace').innerHTML=renderOnboarding();document.getElementById('menu-root').innerHTML='';document.querySelectorAll('.topbar button,.rail button').forEach(b=>b.disabled=true);return;}document.querySelectorAll('.topbar button,.rail button').forEach(b=>b.disabled=false);const profileButton=document.querySelector('[aria-label="Workspace settings"]');if(profileButton)profileButton.textContent=Model.initials(workspace().name||'Recruiter');document.getElementById('task-count').textContent=D.tasks.filter(t=>!t.completed&&t.dueDate<=D.today).length;
 const group=S.profile?'recruit':(['dashboard','tasks','activity'].includes(S.page)?'overview':['candidates','pipeline','liked','watchlists','watchlist','alerts','contacts'].includes(S.page)?'recruit':['search','saved'].includes(S.page)?'search':S.page==='offices'?'manage':S.page==='market'?'research':S.page==='settings'?'settings':['workflows','sequences'].includes(S.page)?S.page:'performance');
 document.querySelectorAll('.rail-button').forEach(b=>b.classList.toggle('active',b.dataset.section===group));
 const views={candidates:renderCandidates,dashboard:renderDashboard,pipeline:renderAgents,liked:renderAgents,search:renderAgents,contacts:renderAgents,watchlist:renderAgents,tasks:renderTasks,activity:renderActivity,watchlists:renderWatchlists,saved:renderSaved,alerts:renderAlerts,settings:renderSettings,offices:renderOffices,market:renderMarket,performance:renderPerformance,workflows:()=>WorkflowUI.render('workflows'),sequences:()=>WorkflowUI.render('sequences')};
 document.getElementById('workspace').innerHTML=S.profile?renderProfile():(views[S.page]||renderCandidates)();renderMenu();CSVImportUI.decorate();
}
function renderMenu(){const menus={overview:[['Dashboard','dashboard','home'],['Activity log','activity','clock'],['Tasks','tasks','task']],recruit:[['Pipeline','pipeline','users'],['Pipeline alerts','alerts','bell'],['Candidates','candidates','target'],['Liked agents','liked','like'],['Watchlists','watchlists','folder'],['CRM contacts','contacts','plus']],manage:[['Office directory','offices','users'],['CRM contacts','contacts','book']],search:[['Agent search','search','search'],['Saved searches','saved','folder']]};
 document.getElementById('menu-root').innerHTML=S.menu?`<div class="menu"><div class="eyebrow">${E(S.menu)}</div>${menus[S.menu].map(([n,p,ic])=>`<button data-action="navigate" data-page="${p}">${icon(ic,16)}${n}</button>`).join('')}</div>`:'';
}
function allCandidates(){return Model.candidates(D.agents,prefs());}
function candidateSet(){return allCandidates().filter(a=>S.category==='All candidates'||a.category===S.category);}
function candidateCard(a){return `<article class="candidate"><div class="candidate-top"><span class="category-label ${a.viewedAt?'viewed':''}">${a.viewedAt?'✓ ':''}${E(a.category||'Candidate')}</span><span class="row" style="gap:1px">${ib('Like '+a.name,'like','like',`data-id="${a.id}"`,a.liked?'active':'')}${ib('Not a good candidate: '+a.name,'reject-candidate','dislike',`data-id="${a.id}"`)}</span></div><button class="candidate-main" data-action="profile" data-id="${a.id}">${avatar(a)}<span class="agent-name">${E(a.name)}</span><span class="agent-office">${E(a.office)}</span></button><div class="candidate-stats"><div class="stat-row"><span class="label">Sales volume</span><strong>${money(a.volume,true)}</strong></div><div class="stat-row"><span class="label">Est. time in industry</span><strong>${a.years??'—'} years</strong></div><div class="stat-row"><span class="label">Most transacted</span><strong>${E(a.city||'—')}</strong></div><div class="stat-row"><span class="label">Potential to move</span>${badge(a.move||'Unknown')}</div></div></article>`;}
function renderCandidates(){return renderAgents();}
function visibleAgents(){let items=D.agents.filter(a=>a.datasetId==='live');if(S.page==='pipeline')items=Model.pipeline(D.mode==='mixed'?items.filter(a=>a.datasetId==='live'):items);if(S.page==='liked')items=items.filter(a=>a.liked&&(D.mode!=='mixed'||a.datasetId==='live'));if(S.page==='contacts')items=items.filter(a=>a.datasetId==='live'||a.manual);if(S.page==='watchlist'){const w=D.watchlists.find(x=>x.id===S.watchlist);items=items.filter(a=>w?.agentIds.includes(a.id));}return Model.sort(Model.filter(items,S.filters),S.sort,S.dir);}
function renderAgents(){const names={candidates:'Candidates',pipeline:'Pipeline',liked:'Liked agents',search:'Agent search',contacts:'CRM contacts',watchlist:D.watchlists.find(w=>w.id===S.watchlist)?.name||'Watchlist'};const agents=visibleAgents(),vol=agents.reduce((n,a)=>n+(a.volume||0),0);const labels=availableColumnNames();const columns=(workspace().columns||Object.keys(columnNames).slice(0,6)).filter(c=>Object.hasOwn(labels,c));const maxPage=Math.max(1,Math.ceil(agents.length/S.pageSize));S.pageNo=Math.min(S.pageNo,maxPage);const shown=agents.slice((S.pageNo-1)*S.pageSize,S.pageNo*S.pageSize);const selected=agents.filter(a=>S.selected.has(a.id));return `${pageHeader(names[S.page],S.page==='pipeline'?'Your recruiting relationships, from first hello to next chapter.':S.page==='search'?'Find the agents who fit your next conversation.':S.page==='contacts'||S.page==='candidates'?'Courted contacts imported to this Mac. Import does not assess recruiting fit.':'Keep your most relevant relationships close.',`${S.page==='contacts'?btn('Add contact','contact','plus','', 'primary')+btn('Add bulk','csv-import-pick','download'):''}${btn(S.insights?'Hide insights':'Show insights','insights','chart')}`)}${S.insights?`<div class="insights">${insight('Agents',agents.length)}${insight('Sales volume',money(vol,true))}${insight('High move potential',agents.filter(a=>a.move==='High').length)}${insight('Liked agents',agents.filter(a=>a.liked).length)}</div>`:''}<div class="between" style="margin-bottom:15px"><div class="filters-bar"><input id="list-query" aria-label="Filter agents" placeholder="Search name, office or city…" value="${E(S.filters.q||'')}" style="width:235px"><select aria-label="Status filter" data-filter="status">${selectOptions(D.stages,S.filters.status,'All statuses')}</select><select aria-label="Move potential filter" data-filter="move">${selectOptions(['High','Moderate','Low','Unknown'],S.filters.move,'Move potential')}</select>${Object.values(S.filters).some(Boolean)?btn('Clear filters','clear-filters','close','','small'):''}</div>${btn('All filters','filters','filter')}</div><section class="card table-card"><div class="table-toolbar between"><span class="sub"><strong style="color:#465d4d">${agents.length}</strong> agents &nbsp;·&nbsp; ${money(vol,true)} sales volume</span><div class="row">${S.page==='search'?btn('Save search','save-search','folder','','small'):''}${ib('Edit columns','columns','settings')}${ib('Export results to CSV','export','download')}</div></div>${selected.length?`<div class="selected-banner">${selected.length} selected ${btn('Add to watchlist','add-watchlist','folder','','small')}${btn('Clear selection','clear-selection','close','','small')}</div>`:''}<div class="table-scroller"><table><thead><tr><th><input type="checkbox" aria-label="Select visible agents" data-select-all ${shown.length&&shown.every(a=>S.selected.has(a.id))?'checked':''}></th><th><button data-action="sort" data-key="name">Agent ${icon('down',11)}</button></th>${columns.map(c=>`<th><button data-action="sort" data-key="${c}">${E(labels[c])}${icon('down',11)}</button></th>`).join('')}</tr></thead><tbody>${shown.map(a=>`<tr><td><input type="checkbox" aria-label="Select ${E(a.name)}" data-select-agent="${a.id}" ${S.selected.has(a.id)?'checked':''}></td><td><button class="table-agent" data-action="profile" data-id="${a.id}">${avatar(a,'tiny')}${E(a.name)}</button></td>${columns.map(c=>`<td>${agentCell(a,c)}</td>`).join('')}</tr>`).join('')}</tbody></table>${!shown.length?empty('No matching agents','Try fewer filters or add a contact to your workspace.'):''}</div><footer class="table-footer"><div class="row">Items per page ${[20,50,100].map(n=>`<button class="${n===S.pageSize?'text-button':''}" data-action="page-size" data-value="${n}">${n}</button>`).join('')}</div><div class="row">${ib('Previous page','page-back','left',S.pageNo===1?'disabled':'')}<span class="page-number">${S.pageNo}</span> of ${maxPage}${ib('Next page','page-next','right',S.pageNo===maxPage?'disabled':'')}</div><span>${agents.length} results</span></footer></section>`;}
function agentCell(a,c){if(c.startsWith('custom:'))return E(a.customValues?.[c.slice(7)]??'—');if(c==='move')return badge(a.move||'Unknown');if(c==='volume')return money(a.volume);if(c==='change')return a.change!=null?`<span class="badge ${a.change<0?'negative':'positive'}">${a.change>0?'+':''}${a.change}%</span>`:'—';if(c==='status')return `<select class="inline-select" aria-label="Status for ${E(a.name)}" data-agent-field="status" data-id="${a.id}">${selectOptions(D.stages,a.status,'No status')}</select>`;if(['viewedAt','lastInteraction'].includes(c))return dateTime(a[c]);return E(a[c]??'—');}
function insight(label,value,detail=''){return `<div class="card insight"><span class="panel-label">${E(label)}</span><div class="value">${E(value)}</div><span class="sub">${E(detail)}</span></div>`;}
function taskMini(t){const a=D.agents.find(x=>x.id===t.agentId);return `<div class="mini-task"><button class="circle-check" data-action="complete-task" data-id="${E(t.id)}" aria-label="Complete ${E(t.title)}"></button><div class="grow"><button class="task-name" data-action="task-detail" data-id="${E(t.id)}">${E(t.title)}</button><p class="sub">${E(a?.name||'Contact')} · ${date(t.dueDate)}</p><div class="task-card-actions">${taskCardActions(t,a)}</div></div>${t.priority==='High'?`<span class="badge negative">High</span>`:''}</div>`;}
function taskCardActions(t,a){const draft=D.drafts.find(d=>d.id===t.draftId),current=t.type==='Message'&&draft?.state==='draft'&&draft?.agentId===t.agentId&&draft?.body===t.draftBody;return `${btn('View details','task-detail','',`data-id="${E(t.id)}"`,'small')}${current&&CommunicationsUI.allowed(a)?btn('Review message','comm-task-message','',`data-id="${E(t.id)}"`,'small soft'):''}`;}
function renderDashboard(){const tasks=Model.tasks(D.tasks,'All open',D.today).slice(0,6),cand=allCandidates().slice(0,3);const stages=D.stages.slice(1,7);return `${pageHeader('Your recruiting day',new Date(D.today+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}),btn('Review candidates','navigate','arrow','data-page="candidates"','primary'))}<div class="dashboard-grid"><div><section class="card"><div class="between"><h2>Tasks to focus on</h2>${ib('View tasks','navigate','arrow','data-page="tasks"')}</div><p class="sub" style="margin-top:8px">Keep the conversation moving.</p>${tasks.length?tasks.map(taskMini).join(''):empty('All caught up','Your next tasks will appear here.','task')}</section><section class="card" style="margin-top:18px"><h3>Your lists</h3><div class="divider"></div>${D.watchlists.map(w=>`<button class="saved-list-row" data-action="watchlist-open" data-id="${w.id}" style="padding:9px 0;width:100%">${icon('folder',16)}<span class="grow" style="text-align:left">${E(w.name)}</span><span class="badge">${w.agentIds.length}</span></button>`).join('')}${btn('Create watchlist','watchlist-create','plus','','small')}</section></div><div><div class="between section-head"><h2>Pipeline summary</h2><button class="text-button" data-action="navigate" data-page="pipeline">View pipeline</button></div><div class="stage-grid">${stages.map((stage,i)=>{const group=D.agents.filter(a=>a.status===stage);return `<button class="card stage" data-action="stage-filter" data-value="${stage}" style="text-align:left"><h3><span class="dot" style="background:${['#aa8ac1','#d8a268','#83a4c9','#78aaa5','#9f92c0','#6c977b'][i]};margin-right:6px"></span>${stage}</h3><div class="number">${group.length} <span class="sub">agents</span></div><p class="sub">${money(group.reduce((n,a)=>n+(a.volume||0),0),true)} sales volume</p></button>`;}).join('')}</div><div class="between section-head" style="margin-top:27px"><div><h2>A few good conversations</h2><p class="sub" style="margin-top:5px">Today's sample candidates</p></div><button class="text-button" data-action="navigate" data-page="candidates">View all</button></div><div class="card-grid">${cand.map(candidateCard).join('')}</div><div class="between section-head" style="margin-top:27px"><h2>Recently viewed</h2></div><div class="card">${D.agents.filter(a=>a.viewedAt).sort((a,b)=>b.viewedAt.localeCompare(a.viewedAt)).slice(0,4).map(a=>`<button class="search-result" data-action="profile" data-id="${a.id}">${avatar(a,'tiny')}<span class="grow">${E(a.name)}</span><span class="sub">${E(a.office)}</span>${icon('right',14)}</button>`).join('')||'<p class="sub">Agent profiles you explore will appear here.</p>'}</div></div></div>`;}
function profileTransactions(a){return Model.transactions(a,S.period,D.today,S.custom);}
function metric(label,value,detail='',trend=null){return `<div class="card metric"><span class="panel-label">${E(label)}</span><div class="row"><div class="value">${value}</div>${trend!=null?`<span class="badge ${trend<0?'negative':'positive'}">${trend>0?'+':''}${trend}%</span>`:''}</div><p class="sub">${E(detail)}</p></div>`;}
function chart(a){const h=a.history||[];const max=Math.max(...h.map(x=>x.volume),1);return `<svg class="chart" viewBox="0 0 780 225" role="img" aria-label="Sample annual sales volume for ${E(a.name)}">${[0,1,2,3].map(i=>`<line x1="45" y1="${180-i*50}" x2="765" y2="${180-i*50}"/><text x="0" y="${183-i*50}">${money(max*i/3,true)}</text>`).join('')}${h.map((v,i)=>{const height=v.volume/max*155,x=70+i*116;return `<rect x="${x}" y="${180-height}" width="47" height="${height*.58}" rx="5" class="chart-bar-alt"/><rect x="${x}" y="${180-height*.42}" width="47" height="${height*.42}" rx="3" class="chart-bar"/><text x="${x+10}" y="205">${v.year}</text>`;}).join('')}</svg><div class="legend"><span><i style="background:#d5e4da"></i>Buy-side</span><span><i style="background:#a7c9b3"></i>List-side</span></div>`;}
function renderProfile(){const a=currentAgent();if(!a)return empty('Agent unavailable','Return to your list.');const i=S.reviewIds.indexOf(a.id),wlists=D.watchlists.filter(w=>w.agentIds.includes(a.id));return `<div class="profile-nav"><div class="row"><button class="text-button" data-action="profile-close">← Back to ${E(S.returnPage==='candidates'?S.category:S.returnPage==='search'?'search':S.returnPage)}</button><span style="color:#d4dcd5">|</span><strong>${E(a.name)}</strong></div><span class="sub">${E(a.category||'Manual contact')}</span><div class="row">${ib('Previous agent','profile-prev','left',i<=0?'disabled':'')}<span class="sub">${Math.max(1,i+1)} of ${Math.max(1,S.reviewIds.length)}</span>${ib('Next agent','profile-next','right',i<0||i>=S.reviewIds.length-1?'disabled':'')}${ib('Close profile','profile-close','close')}</div></div><div class="profile-layout"><aside class="card profile-sidebar"><div class="sidebar-block"><div class="row" style="justify-content:flex-end">${ib('Like agent','like','like',`data-id="${a.id}"`,a.liked?'active':'')}${ib('Add to watchlist','add-watchlist','folder',`data-id="${a.id}"`)}${ib('Edit contact','edit-contact','note',`data-id="${a.id}"`)}</div><div class="profile-title">${avatar(a,'large')}<div style="min-width:0"><h2>${E(a.name)}</h2><p class="agent-office">${E(a.office)}</p><p class="hint">${E(a.source)}</p></div></div><div class="profile-actions">${[['Interaction','interaction','message'],['Task','task-create','task'],['Note','note','note'],['Draft text','draft','spark']].map(([label,ac,ic])=>`<button class="profile-action" data-action="${ac}" data-id="${a.id}"><span class="action-tile ${ic==='spark'?'spark':''}">${icon(ic,19)}</span>${label}</button>`).join('')}</div></div><div class="sidebar-block"><h3>Prospect management</h3><div class="details"><div class="detail-pair"><label>Status</label><select aria-label="Prospect status" data-agent-field="status" data-id="${a.id}">${selectOptions(D.stages,a.status,'No status')}</select></div></div></div><div class="sidebar-block"><h3>Contact info</h3><div class="details">${contactInfoLine('Phone','phone',a.phone)}${contactInfoLine('Email','mail',a.email)}${contactInfoLine('City','location',a.city)}${linkedinContactInfo(a)}${contactInfoLine('Added to Sprout','clock',dateTime(a.createdAt||a.importedAt))}</div>${emailCompanyReviewInfo(a)}<p class="hint" style="margin-top:14px">${a.manual?'Entered locally.':'Fictional contact details for this preview.'}</p>${CommunicationsUI.profileActions(a)}</div><div class="sidebar-block"><h3>Agent info</h3><div class="details">${[['License',a.license],['MLS',a.mls],['Most transacted city',a.city],['Time in industry',a.years!=null?a.years+' years':null],['Time at office',a.officeYears!=null?a.officeYears+' years':null]].map(([k,v])=>`<div class="detail-pair"><label>${k}</label><span>${E(v||'—')}</span></div>`).join('')}</div></div><div class="sidebar-block"><h3>Watchlists</h3><div class="row" style="flex-wrap:wrap;margin-top:13px">${wlists.map(w=>`<span class="chip">${E(w.name)}</span>`).join('')||'<span class="sub">Not on a watchlist yet</span>'}</div>${a.rejectionReason?`<p class="hint" style="margin-top:12px">Thumbs down: ${E(a.rejectionReason)}${a.rejectionDetail?' — '+E(a.rejectionDetail):''}</p>`:''}${a.disposition?`<button class="text-button" data-action="restore-candidate" data-id="${a.id}" style="margin-top:14px">Restore skipped recommendation</button>`:''}</div></aside><section class="profile-main">${pageTabs(['Production','Five-year performance','Specialization','Comparisons','Activity log'],S.profileTab,'profile-tab')}${S.profileTab==='Five-year performance'?PerformanceUI.renderProfile(a,D):S.profileTab==='Production'?renderProduction(a):S.profileTab==='Specialization'?renderSpecialization(a):S.profileTab==='Comparisons'?renderComparison(a):renderTimeline(a.id)}</section></div>`;}
function periods(){return `<div class="periods">${['LTM','YTD','2025','2024','5Y','All time','Custom'].map(p=>`<button class="period ${p===S.period?'active':''}" data-action="period" data-value="${p}">${p}</button>`).join('')}</div>`;}
function renderProduction(a){const txs=profileTransactions(a),m=Model.metrics(txs);return `<div class="between"><h2>Production overview</h2>${periods()}</div>${!a.transactions?.length?`<div class="card" style="margin-top:18px">${empty('Production not added','This contact has no production history. Unknown values stay blank.','chart')}</div>`:`<div class="metric-grid">${metric('Sales volume',money(m.volume),`${S.period} · sample transactions`)}${metric('Average sales price',money(m.avg),`${m.units} closed transactions`)}${metric('Approx. GCI',money(m.gci),'Illustration at 2.75%; before splits')}${metric('Units closed',m.units,`${m.buy} Buy-side   ·   ${m.list} List-side`)}${metric('Listing efficiency',a.closeRatio+'%',`${a.dom} avg. days on market · sample LTM`)}${metric('Rentals',a.rentals,'Sample LTM count')}${metric('Current activity',a.active??'—',`${a.pending??'—'} pending · ${a.active??'—'} active listings`)}${metric('Potential to grow',badge(a.growth||'Unknown'),'Illustrative sample assessment')}${metric('Potential to move',badge(a.move||'Unknown'),'Sample forecast · not independently scored')}</div><div class="profile-section"><div class="between"><h2>Production over time</h2><span class="sub">Annual sample history</span></div><div class="card">${chart(a)}</div></div><div class="profile-section"><h2>Why this agent appears</h2><div class="card">${(a.signals||[]).map(s=>`<div class="row" style="align-items:flex-start;padding:10px 0"><span class="timeline-icon">${icon('spark',16)}</span><div><h3>${E(s.label)}</h3><p class="sub" style="margin-top:5px">${E(s.detail)}</p></div></div>`).join('')}</div></div><div class="profile-section"><div class="between"><h2>Real estate activity</h2><span class="sub">${txs.length} activities · ${S.period}</span></div><div class="card table-card">${transactionTable(txs)}</div></div><div class="profile-section"><h2>Transaction geography</h2><div class="card"><div class="map-placeholder"><div class="map-label">${icon('location',25)}<strong>${E(a.city)}</strong><span class="sub">Sample locations · no map service connected</span></div></div></div></div>`}`;}
function transactionTable(txs){return `<div class="table-scroller"><table><thead><tr><th>Date</th><th>Activity</th><th>Price</th><th>Address</th><th>Deal side</th></tr></thead><tbody>${txs.map(t=>`<tr><td>${date(t.date)}</td><td>${E(t.activity)}</td><td>${money(t.price)}</td><td>${E(t.address)}</td><td>${E(t.side)}</td></tr>`).join('')}</tbody></table>${txs.length?'':empty('No activity in this period','Choose another period to see this sample agent’s transactions.','chart')}</div>`;}
function breakdown(title,rows){const total=rows.reduce((n,r)=>n+r.value,0)||1;return `<div class="card"><h2>${E(title)}</h2>${rows.map(r=>`<div class="breakdown-row"><div class="between"><span>${E(r.label)}</span><span class="sub">${r.value} · ${Math.round(r.value/total*100)}%</span></div><div class="bar-track"><div class="bar-fill" style="width:${r.value/total*100}%"></div></div></div>`).join('')}</div>`;}
function renderSpecialization(a){const t=profileTransactions(a),m=Model.metrics(t);const ranges=[['Under $250K',0,250000],['$250K–$500K',250000,500000],['$500K–$750K',500000,750000],['$750K–$1M',750000,1000000],['$1M+',1000000,Infinity]];return `<div class="between" style="margin-bottom:20px"><h2>Business specializations</h2>${periods()}</div>${t.length?`<div class="dual-grid">${breakdown('Production by location',[{label:a.city,value:t.length}])}${breakdown('Production by price point',ranges.map(([label,lo,hi])=>({label,value:t.filter(x=>x.price>=lo&&x.price<hi).length})))}${breakdown('Deal side',[{label:'Buy-side',value:m.buy},{label:'List-side',value:m.list}])}${breakdown('Property type',[{label:'Single family',value:t.length}])}</div><p class="bottom-note">${icon('shield',13)} Breakdowns use the selected period’s fictional transactions.</p>`:empty('No production to break down','Select a different period or a sample agent with activity.','chart')}`;}
function renderComparison(a){let peers=D.agents.filter(x=>x.id!==a.id&&!x.manual);if(S.comparison==='Similar agents')peers=peers.filter(x=>Math.abs(x.years-a.years)<=3);if(S.comparison==='Same city')peers=peers.filter(x=>x.city===a.city);if(S.comparison==='Same office')peers=peers.filter(x=>x.office===a.office);const average=k=>peers.length?peers.reduce((n,p)=>n+(p[k]||0),0)/peers.length:null;return `<div class="between" style="margin-bottom:20px"><h2>${E(a.name)} vs.</h2><select aria-label="Comparison group" data-comparison>${selectOptions(['Similar agents','Same city','Same office','All sample agents'],S.comparison)}</select></div><div class="card table-card"><div class="table-toolbar"><h3>Production comparison</h3><p class="sub" style="margin-top:5px">LTM sample metrics · ${peers.length} agents in comparison group</p></div><table><thead><tr><th>Metric</th><th>${E(a.name)}</th><th>Peer average</th></tr></thead><tbody>${[['Sales volume','volume',true],['Units','units',false],['Years in industry','years',false],['Active listings','active',false],['Average days on market','dom',false]].map(([label,k,currency])=>`<tr><td>${label}</td><td>${currency?money(a[k]):E(a[k]??'—')}</td><td>${average(k)==null?'—':currency?money(average(k)):average(k).toFixed(1)}</td></tr>`).join('')}</tbody></table></div><div class="profile-section"><h2>Agents in this comparison</h2><div class="card">${peers.slice(0,6).map(p=>`<button class="search-result" data-action="profile" data-id="${p.id}">${avatar(p,'tiny')}<span class="grow">${E(p.name)}</span><span class="sub">${money(p.volume,true)}</span>${icon('right',14)}</button>`).join('')||'<p class="sub">No peers match this group.</p>'}</div></div>`;}
function renderCommunicationAttempts(aid){if(!aid)return '';const rows=(D.communications||[]).filter(r=>r.agentId===aid).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));return `<section class="card comm-history"><h3>In-app communication attempts</h3><p class="hint">These are attempts started in Sprout Recruit. Their saved outcome is shown below; opening another app alone does not prove a send.</p>${rows.length?rows.map(r=>{const state=String(r.state||'unknown'),label=CommunicationsUI.stateLabels[state]||state,channel=r.channel==='call'?'Call':'Message';return `<article class="comm-attempt"><div class="between"><strong>${E(channel)} · ${E(r.phone||'Number unavailable')}</strong><span class="badge">${E(label)}</span></div><p class="sub">${E(r.transport||'Local handoff')} · ${E(dateTime(r.createdAt||r.updatedAt))}</p>${r.body?`<p class="comm-message">${E(r.body)}</p>`:''}${r.providerId?`<p class="hint">Provider ID: ${E(r.providerId)}</p>`:''}</article>`;}).join(''):'<p class="sub">No in-app communication attempts saved for this contact.</p>'}</section>`;}
function renderExternalMessages(aid){if(!aid)return '';const rows=(D.externalMessages||[]).filter(r=>r.agentId===aid&&r.channel!=='Email').sort((a,b)=>String(a.occurredAt||'').localeCompare(String(b.occurredAt||'')));if(!rows.length)return '';return `<section class="card comm-history"><h3>Imported message correspondence</h3><p class="hint">Saved copies of exact external messages. Importing a message does not change CRM status or prove delivery.</p>${rows.map(r=>`<article class="comm-attempt"><div class="between"><strong>${E(r.channel||'Message')} · ${E(r.direction==='inbound'?'Received from':'Sent to')} ${E(r.direction==='inbound'?r.from:r.to)}</strong><span class="badge">${E(r.provider||'External')}</span></div><p class="sub">${E(dateTime(r.occurredAt))}${r.subject?' · '+E(r.subject):''}</p><p class="comm-message">${E(r.body||'')}</p><p class="hint">Message ID: ${E(r.providerMessageId||'')} · Thread ID: ${E(r.providerThreadId||'')}</p></article>`).join('')}</section>`;}
function renderEmailActivity(r,aid){
 const a=D.agents.find(x=>x.id===r.agentId),inbound=r.direction==='inbound';
 return `<article class="timeline-item imported-email"><span class="timeline-icon">${icon('mail',16)}</span><div class="grow"><div class="between"><div><h3>Email ${inbound?'received':'sent'} · ${E(r.subject||'(no subject)')}</h3><p class="sub">${!aid?E(a?.name||'Contact')+' · ':''}${E(dateTime(r.occurredAt))} · Imported from ${E(r.provider||'Gmail')}</p></div></div><p class="sub">From: ${E(r.from||'')} · To: ${E(r.to||'')}</p><p class="comm-message">${E(r.body||'')}</p><p class="hint">Message ID: ${E(r.providerMessageId||'')} · Thread ID: ${E(r.providerThreadId||'')}</p></div></article>`;
}
function renderTimeline(aid=null){
 const local=(D.activities||[]).filter(a=>!aid||a.agentId===aid).map(record=>({kind:record.kind,date:record.date,pinned:!!record.pinned,record}));
 const emails=(D.externalMessages||[]).filter(r=>r.channel==='Email'&&(!aid||r.agentId===aid)).map(record=>({kind:'email',date:record.occurredAt,pinned:false,record}));
 const items=[...local,...emails].filter(item=>S.activityKind==='All'||item.kind===S.activityKind).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||String(b.date||'').localeCompare(String(a.date||'')));
 return `<p class="hint" role="note">This log contains saved local activity and correspondence imported after exact identity checks. Gmail and Apple Messages are not automatically synced. A CRM status change alone does not import a message; a saved Sent email does not prove delivery.</p>${renderExternalMessages(aid)}${renderCommunicationAttempts(aid)}<div class="between" style="margin-bottom:18px"><span class="sub">${items.length} activities</span><select aria-label="Activity type" data-activity-filter>${selectOptions(['All','email','note','interaction','task','status','draft','system'],S.activityKind)}</select></div><div class="timeline">${items.map(item=>{
  if(item.kind==='email')return renderEmailActivity(item.record,aid);
  const a=D.agents.find(x=>x.id===item.record.agentId),activity=item.record;
  const draftTasks=activity.kind==='draft'?D.tasks.filter(t=>t.agentId===activity.agentId&&t.type==='Message'&&D.drafts.some(d=>d.id===t.draftId&&d.state==='draft')):[];
  const linkedTask=draftTasks.find(t=>t.draftId===activity.draftId)||draftTasks.find(t=>t.draftBody===activity.body)||(draftTasks.length===1?draftTasks[0]:null);
  return `<article class="timeline-item ${activity.pinned?'pinned':''}"><span class="timeline-icon">${icon({note:'note',interaction:'message',task:'task',status:'users',draft:'spark',system:'clock'}[activity.kind],16)}</span><div class="grow"><div class="between"><div><h3>${linkedTask?`<button class="timeline-open" data-action="task-detail" data-id="${E(linkedTask.id)}">${E(activity.title)} · Open ${linkedTask.draftBody===activity.body?'draft':'current draft'}</button>`:E(activity.title)}</h3><p class="sub">${!aid?E(a?.name||'Contact')+' · ':''}${E(activity.author)} · ${dateTime(activity.date)}${activity.kind==='draft'?' · Not sent':''}</p></div>${ib(activity.pinned?'Unpin activity':'Pin activity','pin','pin',`data-id="${activity.id}"`,activity.pinned?'active':'')}</div>${activity.body?`<p>${E(activity.body)}</p>`:''}</div></article>`;
 }).join('')||empty('Your story starts here','Add a note or log an interaction to build this relationship’s history.','note')}</div>`;
}
function renderActivity(){return `${pageHeader('Activity log','A clear record of your recruiting conversations and follow-through.')}${renderTimeline()}`;}
function renderTasks(){const counts={'All open':D.tasks.filter(t=>!t.completed).length,'Today':D.tasks.filter(t=>!t.completed&&t.dueDate===D.today).length,'Overdue':D.tasks.filter(t=>!t.completed&&t.dueDate<D.today).length,'Upcoming':D.tasks.filter(t=>!t.completed&&t.dueDate>D.today).length,'Completed':D.tasks.filter(t=>t.completed).length};const items=Model.tasks(D.tasks,S.taskBucket,D.today,S.taskQ);return `${pageHeader('Tasks','The next step in every relationship.',btn('Create task','task-create','plus','','primary'))}${pageTabs(Object.entries(counts).map(([label,count])=>({label,count})),S.taskBucket,'task-bucket')}<div class="card table-card"><div class="table-toolbar between"><span class="sub">${items.length} tasks</span><input id="task-query" aria-label="Search tasks" placeholder="Search tasks…" value="${E(S.taskQ)}"></div><div class="table-scroller"><table><thead><tr><th>Status</th><th>Title</th><th>Due date</th><th>Type</th><th>Related to</th><th>Priority</th><th>Actions</th></tr></thead><tbody>${items.map(t=>{const a=D.agents.find(x=>x.id===t.agentId);return `<tr><td>${t.completed?`<span class="badge high">${icon('check',12)} Done</span>`:`<button class="circle-check" data-action="complete-task" data-id="${t.id}" aria-label="Complete ${E(t.title)}"></button>`}</td><td><button class="task-title-button" data-action="task-detail" data-id="${t.id}">${E(t.title)}${t.repeatDays?` <span class="muted">↻</span>`:''}</button></td><td><span class="${!t.completed&&t.dueDate<D.today?'badge negative':''}">${date(t.dueDate)}</span></td><td>${E(t.type)}</td><td><button class="text-button" data-action="profile" data-id="${t.agentId}">${E(a?.name||'Contact')}</button></td><td>${badge(t.priority)}</td><td><div class="task-card-actions">${taskCardActions(t,a)}</div></td></tr>`;}).join('')}</tbody></table>${items.length?'':empty('All clear here','Create a task or choose another view.','task')}</div></div>`;}
function renderWatchlists(){return `${pageHeader('Watchlists','Keep the right agents together.',btn('Create watchlist','watchlist-create','plus','','primary'))}<div class="alert-grid">${D.watchlists.map(w=>`<article class="card"><span class="timeline-icon">${icon('folder',19)}</span><h2 style="margin:18px 0 8px">${E(w.name)}</h2><p class="sub">${w.agentIds.length} agents · Private on this Mac</p><div class="divider"></div><div class="between">${btn('Open list','watchlist-open','arrow',`data-id="${w.id}"`)}${ib('Edit watchlist','watchlist-edit','note',`data-id="${w.id}"`)}</div></article>`).join('')||empty('Create your first watchlist','Group agents by market, production or next step.','folder')}</div>`;}
function renderSaved(){return `${pageHeader('Saved searches','Your criteria, ready whenever you need them.')}<div class="card">${D.searches.map(s=>`<div class="saved-list-row">${icon('search',20)}<div class="grow"><h3>${E(s.name)}</h3><p class="sub">${Object.entries(s.filters).filter(([,v])=>v).map(([k,v])=>E(k)+': '+E(v)).join(' · ')||'All agents'}</p></div>${btn('Run search','run-search','arrow',`data-id="${s.id}"`)}</div>`).join('')||empty('Save your first search','Choose filters in Agent Search, then save the criteria for later.','search',btn('Open Agent Search','navigate','arrow','data-page="search"'))}</div>`;}
function renderAlerts(){const alerts=D.alerts.filter(a=>!a.dismissed);return `${pageHeader('Pipeline alerts','Timely reasons to reconnect.',btn('Definitions','alert-definitions','book'))}<div class="alert-grid">${alerts.map(al=>{const a=D.agents.find(x=>x.id===al.agentId);return `<article class="card alert-card"><div class="between"><span class="eyebrow">${E(al.title)}</span>${ib('Dismiss alert','dismiss-alert','close',`data-id="${al.id}"`)}</div><button class="search-result" style="padding:8px 0" data-action="profile" data-id="${a.id}">${avatar(a)}<span><span class="agent-name">${E(a.name)}</span><span class="agent-office" style="display:block">${E(a.office)}</span></span></button><p class="sub" style="margin-top:11px">${E(al.body)}</p><div class="between" style="margin-top:19px"><span class="sub">${money(a.volume,true)} sales volume</span>${badge(a.move)}</div><footer><button class="text-button" data-action="interaction" data-id="${a.id}">Log check-in</button><button class="text-button" data-action="draft" data-id="${a.id}">Prepare draft</button><span class="grow"></span><span class="sub">${date(al.date).split(',')[0]}</span></footer></article>`;}).join('')||empty('No new alerts','New local alert records will appear here.','bell')}</div>`;}
function offices(){const sample=D.agents.filter(a=>a.datasetId==='sample'||String(a.id||'').startsWith('sample-'));return [...new Set(sample.map(a=>a.office))].map(name=>{const agents=sample.filter(a=>a.office===name);return{name,agents,volume:agents.reduce((n,a)=>n+(a.volume||0),0)};});}
function renderOffices(){return `${pageHeader('Office directory','Brokerages represented in your local sample workspace.')}<div class="alert-grid">${offices().map(o=>`<article class="card"><span class="timeline-icon">${icon('users',20)}</span><h2 style="margin:16px 0 8px">${E(o.name)}</h2><p class="sub">${o.agents.length} agents · ${money(o.volume,true)} sample volume</p><div class="divider"></div>${btn('View agents','office-search','arrow',`data-value="${E(o.name)}"`)}</article>`).join('')}</div>`;}
function renderMarket(){const sample=D.agents.filter(a=>a.datasetId==='sample'||String(a.id||'').startsWith('sample-'));const total=sample.reduce((n,a)=>n+(a.volume||0),0);return `${pageHeader('Sample overview','An overview of the fictional sample records on this Mac. This is not an MLS market report.')}<div class="insights">${insight('Sample agents',sample.length)}${insight('Represented offices',offices().length)}${insight('Sample sales volume',money(total,true))}${insight('Markets',new Set(sample.map(a=>a.city)).size)}</div><div class="dual-grid">${breakdown('Sample agents by market',[...new Set(sample.map(a=>a.city))].map(city=>({label:city||'Not added',value:sample.filter(a=>a.city===city).length})))}${breakdown('Sample move potential',['High','Moderate','Low','Unknown'].map(move=>({label:move,value:sample.filter(a=>a.move===move).length})))}</div>`;}
function renderPerformance(){return PerformanceUI.renderReport(D);}
function timezoneField(value){return field('Display time zone','timezone','text',value||Intl.DateTimeFormat().resolvedOptions().timeZone,'required maxlength="100" placeholder="America/Chicago"')+'<p class="hint">Use an IANA zone such as America/Chicago. Recorded instants display in this time zone. Dates without a recorded time stay date-only. Manual date/time entry uses this Mac’s local time zone.</p>';}
function profileFields(w){return field('Your name','name','text',w.name||'','required maxlength="120" autocomplete="name"')+field('Company','company','text',w.company||'Sprout Realty','required maxlength="160" autocomplete="organization"')+field('Role','role','text',w.role||'Recruiter','maxlength="120"')+timezoneField(w.timezone);}
function renderOnboarding(){return `<section class="onboarding card"><span class="eyebrow">Sprout internal pilot</span><h1>Set up your workspace</h1><p class="sub">Your contacts, notes, tasks and drafts stay on this Mac. Enter your own recruiter identity before you begin. Existing saved records are preserved.</p><form id="onboarding-form">${profileFields(workspace())}<p class="hint">Account connections, AI execution and automated outreach are planned for a later phase. This setup does not connect an account or send a message.</p><p class="form-error" id="onboarding-error" role="alert"></p><button class="button primary" type="submit">Create my workspace profile</button></form></section>`;}
async function refreshRecovery(){try{recoveryState=await native('recovery.list');recoveryError='';}catch(error){recoveryError=error.message;}if(S.page==='settings'&&S.settingsTab==='Local data')render();}
function renderRecovery(){return `<section class="card"><h2>Local recovery</h2><p class="sub">Verified snapshots contain your local database and managed attachments. Restore replaces this workspace after a confirmation and requires restarting the app. A recovery copy of the current workspace is kept first.</p><p class="path">${E(D.databasePath)}</p><div class="comm-actions">${btn('Create recovery snapshot','recovery-create','download')}${btn('Restore local snapshot…','recovery-restore')}${btn('Refresh snapshots','recovery-refresh')}</div><p class="hint">Snapshots stay on this Mac and are retained until a cleanup policy is approved. They do not protect against loss of the device. Keychain account secrets are not exported.</p>${recoveryError?`<p class="form-error" role="alert">${E(recoveryError)}</p>`:''}${recoveryState?`<h3>Saved snapshots</h3><p class="path">${E(recoveryState.root||'')}</p>${recoveryState.snapshots?.length?`<ul class="recovery-list">${recoveryState.snapshots.map(r=>`<li><strong>${E(dateTime(r.createdAt))}</strong> · ${E(r.reason)}<span class="path">${E(r.path)}</span></li>`).join('')}</ul>`:'<p class="sub">No snapshots listed yet. Create one before making substantial changes.</p>'}`:'<p class="sub">Choose Refresh snapshots to see saved recovery points.</p>'}</section>${renderHistoryAudit()}`;}
function renderHistoryAudit(){const audit=historyAuditState;return `<section class="card"><h2>Historical evidence review</h2><p class="sub">Check for missing times, older date-only records and follow-up drafts that may need review after a reply. This check reads saved records and changes nothing.</p>${btn('Review saved history','history-audit')}${historyAuditError?`<p class="form-error" role="alert">${E(historyAuditError)}</p>`:''}${audit?`<p class="sub">Checked ${E(dateTime(audit.generatedAt))} · ${E(audit.totalFindings)} findings</p><p class="hint">${E(audit.interpretation)}</p>${audit.totalFindings?`<ul>${Object.entries(audit.findingCounts||{}).map(([code,count])=>`<li>${E(code.replaceAll('_',' '))}: ${E(count)}</li>`).join('')}</ul><details><summary>Review record references (${E((audit.findings||[]).length)} shown)</summary>${(audit.findings||[]).map(f=>`<article class="comm-attempt"><h3>${E(f.code.replaceAll('_',' '))}</h3><p class="sub">${E(f.kind)} · ${E(f.recordId)}</p><p>${E(f.recommendation)}</p>${D.agents?.some(a=>a.id===f.agentId)?btn('View related contact','profile','',`data-id="${E(f.agentId)}"`):''}</article>`).join('')}</details>${audit.detailsTruncated?'<p class="hint">This screen shows the first 200 record references. Counts cover the full audit; use the developer audit command for additional details.</p>':''}`:'<p class="sub">No findings in the checks performed. This does not verify external delivery or source accuracy.</p>'}`:''}</section>`;}
function renderSettings(){const w=workspace();if(!['Workspace','Drafting','Calling & texts','Integrations','Local data'].includes(S.settingsTab))S.settingsTab='Integrations';return `${pageHeader('Settings','A workspace that works your way.')}<div class="settings-grid"><nav class="settings-nav">${['Workspace','Drafting','Calling & texts','Integrations','Local data'].map(n=>`<button type="button" class="${S.settingsTab===n?'active':''}" data-action="settings-tab" data-value="${n}">${n}</button>`).join('')}</nav><div>${S.settingsTab==='Calling & texts'?CommunicationsUI.render():S.settingsTab==='Integrations'?`<section class="card"><h2>Account connections: next phase</h2><p class="sub">This pilot supports local contacts, imports, notes, tasks and reviewed drafts. Each recruiter will connect their own accounts when integrations are ready.</p><p class="hint">AI execution, background inbox sync, automated sourcing, follow-up sequences, provider SMS and iPhone recording are unavailable in this pilot. Existing saved records and connection credentials are preserved; no account is connected or disconnected here.</p></section>`:S.settingsTab==='Local data'?renderRecovery():`<form id="settings-form"><div class="card"><h2>${S.settingsTab==='Drafting'?'Drafting preferences':'Your profile'}</h2><p class="sub">${S.settingsTab==='Drafting'?'Keep your voice and context close. Drafts always need your review.':'Used for new local activity attribution and draft starters. Updating your profile does not rewrite past records.'}</p>${S.settingsTab==='Drafting'?field('Drafting guidance','instructions','textarea',w.instructions||'','maxlength="10000"'):profileFields(w)}<p class="form-error" id="settings-error" role="alert"></p><button class="button primary" type="submit">Save changes</button></div></form>`}</div></div>`;}

function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${E(label)}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${extra}>${E(value)}</textarea>`:`<input id="f-${name}" type="${type}" name="${name}" value="${E(value)}" ${extra}>`}</div>`;}
function selectField(label,name,items,value,blank){return `<div class="field"><label for="f-${name}">${E(label)}</label><select id="f-${name}" name="${name}">${selectOptions(items,value,blank)}</select></div>`;}
function checkbox(label,name,checked=false){return `<label class="checkbox-label"><input type="checkbox" name="${name}" ${checked?'checked':''}>${E(label)}</label>`;}
function agentSelect(aid){return `<div class="field"><label for="f-agentId">Related to</label><select id="f-agentId" name="agentId" required>${D.agents.map(a=>`<option value="${a.id}" ${a.id===aid?'selected':''}>${E(a.name)}</option>`).join('')}</select></div>`;}
function localDayOffset(n){const d=new Date(D.today+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function businessDue(){const d=new Date(D.today+'T12:00:00');let days=0;while(days<3){d.setDate(d.getDate()+1);if(d.getDay()!==0&&d.getDay()!==6)days++;}return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
let lastFocus=null;
function modal(title,body,kind='',footer='',attrs='',drawer=false,wide=false){lastFocus=document.activeElement;S.menu=null;renderMenu();document.getElementById('overlay').innerHTML=`<div class="modal-backdrop ${drawer?'drawer-backdrop':''}"><section class="modal ${drawer?'drawer':''} ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head between"><h2 class="modal-title" id="modal-title">${E(title)}</h2>${ib('Close dialog','close-modal','close')}</header><form id="modal-form" data-kind="${kind}" ${attrs} style="display:contents"><div class="modal-body">${body}<p class="form-error" id="form-error" role="alert"></p></div><footer class="modal-footer">${btn('Cancel','close-modal')}${footer|| (kind?'<button class="button primary" type="submit">Save</button>':'')}</footer></form></section></div>`;requestAnimationFrame(()=>{const el=document.querySelector('.modal input:not([type=checkbox]),.modal textarea,.modal select,.modal button');el?.focus();});}
function closeModal(){document.getElementById('overlay').innerHTML='';lastFocus?.isConnected&&lastFocus.focus();}
function requestCloseModal(){
 if(typeof CSVImportUI!=='undefined'&&CSVImportUI.isBusy?.()){toast('Wait for the CSV operation to finish.');return false;}
 const form=document.getElementById('modal-form');
 if(form&&dirtyForms.has(form)){
  const out=document.getElementById('form-error');
  if(out){out.innerHTML=`Unsaved changes are still in this dialog. Save them or ${btn('Discard changes','discard-modal','','','small')}.`;out.querySelector('button')?.focus();}
  return false;
 }
 closeModal();return true;
}
function candidateFeedbackForm(id){const a=D.agents.find(x=>x.id===id);if(!a)return;modal('Why is '+a.name+' not a good candidate?',selectField('Reason','reason',['Outside target market','Production too low','Too little experience','Poor fit for Sprout','Information is inaccurate','Already reviewed','Other'],'','Choose a reason')+field('Details (optional unless Other)','detail','textarea','','maxlength="1000" placeholder="What should future recommendations take into account?"')+'<p class="hint">This removes this agent from Candidates and saves your feedback locally. Broader sourcing rules require review before they are applied.</p>','candidate-feedback','<button class="button primary" type="submit">Save feedback</button>',`data-id="${id}"`);}
function preferences(){const p=prefs();modal('Candidate preferences',`<p class="sub">Shape which sample agents appear in your daily view.</p><div class="divider"></div><h3>Locations</h3><p class="hint">Leave all unchecked to include every sample market.</p><div class="row" style="flex-wrap:wrap;margin:16px 0 24px">${[...new Set(D.agents.map(a=>a.city))].filter(Boolean).sort().map(c=>`<label class="checkbox-label chip"><input type="checkbox" name="cities" value="${E(c)}" ${p.cities.includes(c)?'checked':''}>${E(c)}</label>`).join('')}</div>${[['LTM sales volume','Volume'],['Closed units','Units'],['Average sales price','Price'],['Years in industry','Years']].map(([label,key])=>`<div class="between" style="margin:12px 0"><h3>${label}</h3>${checkbox('Must have','must'+key,p['must'+key])}</div><div class="field-row">${field('Minimum','min'+key,'number',p['min'+key]||'','min="0" step="any"')}${field('Maximum','max'+key,'number',p['max'+key]||'','min="0" step="any" placeholder="No maximum"')}</div>`).join('')}${selectField('Daily sample limit','dailyLimit',['10','15','20'],String(p.dailyLimit))}<p class="hint">These preferences filter the local sample set. They do not run a live sourcing model.</p>`,'preferences','<button class="button primary" type="submit">Save preferences</button>');}
function contactForm(id){const a=D.agents.find(a=>a.id===id)||{};modal(id?'Edit contact':'Add contact',field('Name','name','text',a.name||'','required maxlength="120"')+field('Company / brokerage','office','text',a.office||'')+field('City','city','text',a.city||'')+field('Email','email','email',a.email||'')+field('Phone','phone','text',a.phone||'')+field('LinkedIn profile URL','linkedinUrl','url',a.linkedinUrl||'','placeholder="https://www.linkedin.com/in/…"')+`<p class="hint">Check that the email domain fits the current brokerage. The app flags possible mismatches for review after saving. Contact details stay on this Mac.</p>`,'contact','',id?`data-id="${id}"`:'');}
function taskFields(t={}){return `<div class="field-row">${selectField('Type','type',['Check-in','Call','Email','Message','Meeting','To-do'],t.type||'Check-in')}${selectField('Priority','priority',['None','Low','Medium','High'],t.priority||'None')}</div>${field('Title','title','text',t.title||'','required maxlength="200" placeholder="What is the next step?"')}<div class="field-row">${field('Due date','dueDate','date',t.dueDate||businessDue(),'required')}${selectField('Repeat after completion','repeatDays',['0','1','7','14','30'],String(t.repeatDays||0))}</div><p class="hint" style="margin-top:-12px;margin-bottom:18px">0 = no repeat. Other values are days after completion or the prior due date, whichever is later.</p>${field('Description','description','textarea',t.description||'','maxlength="10000" placeholder="Add context for your future self…"')}`;}
function editTask(id){const t=D.tasks.find(t=>t.id===id);if(!t)throw Error('This task is no longer available.');const linked=!!t.draftId;modal(linked?'Reschedule draft review':'Edit task',linked?`<p class="sub">${E(t.title)}</p><p class="hint">The title and message stay linked to the exact saved draft. You can change its due date and priority here.</p>${field('Due date','dueDate','date',t.dueDate,'required')}${selectField('Priority','priority',['None','Low','Medium','High'],t.priority||'None')}`:taskFields(t),'task-edit','<button class="button primary" type="submit">Save task</button>',`data-id="${E(id)}"`);}

function taskForm(aid){modal('Create task',agentSelect(aid||S.profile||D.agents[0]?.id)+taskFields(),'task','<button class="button primary" type="submit">Create task</button>');}
function localDateTimeNow(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function activityForm(kind,aid){const interaction=kind==='interaction';modal(interaction?'Log interaction':'Add note',agentSelect(aid||S.profile||D.agents[0]?.id)+(interaction?`<div class="field-row">${selectField('Activity','type',['Check-in','Call','Email','Message','Meeting'],'Check-in')}${selectField('Outcome','outcome',['Completed','Connected','Left voicemail','No answer','No response'],'Completed')}</div>${field('Completed date and time (this Mac’s local time)','dateTime','datetime-local',localDateTimeNow(),`required max="${localDateTimeNow()}"`)}`:'')+field(interaction?'What happened?':'Your note','body','textarea','','required maxlength="10000" placeholder="Keep the details you’ll want for the next conversation…"')+checkbox('Create a follow-up task','createTask')+`<div id="followup-fields" hidden style="margin-top:20px"><div class="field-row">${field('Task title','followTitle','text','','maxlength="200"')}${field('Due date','followDate','date',businessDue())}</div></div><p class="hint" style="margin-top:15px">${interaction?'Record an interaction you completed. This does not send a message or make a call.':'Notes stay in this local workspace.'}</p>`,'activity',`<button class="button primary" type="submit">${interaction?'Log interaction':'Save note'}</button>`,`data-activity="${kind}"`);}
function filterForm(){const f=S.filters;modal('All filters',`<div class="filters-layout"><div>${field('Agent, office or city','q','text',f.q||'')}${selectField('Most transacted city','city',[...new Set(D.agents.map(a=>a.city))].filter(Boolean).sort(),f.city,'All cities')}${selectField('Potential to move','move',['High','Moderate','Low','Unknown'],f.move,'Any potential')}${selectField('Status','status',D.stages,f.status,'Any status')}<div class="field-row">${field('Min. sales volume','minVolume','number',f.minVolume||'','min="0"')}${field('Max. sales volume','maxVolume','number',f.maxVolume||'','min="0"')}</div><div class="field-row">${field('Min. years in industry','minYears','number',f.minYears||'','min="0"')}${field('Max. active listings','maxActive','number',f.maxActive??'','min="0"')}</div></div><aside class="filter-summary"><h3>Refine your criteria</h3><p class="sub">Filters apply together. Missing production is excluded when a production filter is active.</p><div class="divider"></div><p class="sub">Changes apply when you choose Apply filters. Cancel keeps your current view.</p></aside></div>`,'filters','<button class="button primary" type="submit">Apply filters</button>','',true);}
function columnsForm(){const labels=availableColumnNames();const selected=workspace().columns.filter(c=>Object.hasOwn(labels,c));const order=[...selected,...Object.keys(labels).filter(c=>!selected.includes(c))];modal('Edit columns',`<p class="sub">Choose the fields you use most. Your name column always stays visible. Private address and note fields are optional local display columns and remain excluded from CSV exports.</p><div class="divider"></div><div id="column-list">${order.map(c=>`<div class="column-option" data-column="${c}"><label class="checkbox-label"><input type="checkbox" name="columns" value="${c}" ${selected.includes(c)?'checked':''}>${E(labels[c])}</label><div class="row">${ib('Move '+labels[c]+' up','column-up','left')}${ib('Move '+labels[c]+' down','column-down','right')}</div></div>`).join('')}</div>`,'columns');}
function watchlistForm(id){const w=D.watchlists.find(w=>w.id===id);modal(w?'Edit watchlist':'Create watchlist',field('Name','name','text',w?.name||'','required maxlength="100" placeholder="e.g. Austin conversations"')+`<label class="field-label">Agents</label><div class="scroll-list" style="margin-top:10px">${D.agents.map(a=>`<label><input type="checkbox" name="agentIds" value="${a.id}" ${(w?.agentIds||[]).includes(a.id)?'checked':''}>${E(a.name)} <span class="muted">· ${E(a.city)}</span></label>`).join('')}</div><p class="hint">Private on this Mac.</p>`,'watchlist','',id?`data-id="${id}"`:'');}
function addWatchlist(aid){const ids=aid?[aid]:Array(S.selected);modal('Add to watchlist',`<p class="sub" style="margin-bottom:18px">Add ${ids.length} agent${ids.length===1?'':'s'} to an existing list, or name a new one.</p><div class="field"><label for="f-listId">Existing watchlist</label><select id="f-listId" name="listId"><option value="">Create a new watchlist</option>${D.watchlists.map(w=>`<option value="${w.id}">${E(w.name)}</option>`).join('')}</select></div>${field('New watchlist name','name','text','','maxlength="100"')}`,'add-watchlist','',`data-agent-ids="${E(JSON.stringify(ids))}"`);}
function draftForm(aid){const a=D.agents.find(x=>x.id===(aid||S.profile))||D.agents[0];const draft=D.drafts.filter(d=>d.agentId===a.id&&d.channel==='Message').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];modal('Draft workspace',`<div class="draft-note">Saving a draft does not send it. Open in Messages starts a separate review and handoff. Starter wording is a local template, not AI-generated.</div>${agentSelect(a.id)}<div class="field-row">${selectField('Contact method','channel',['Message','Email','Phone call'],draft?.channel||'Message')}<div class="field"><label>Starting point</label>${btn('Prepare starter','prepare-draft','spark')}</div></div>${field('Draft','body','textarea',draft?.body||'','required style="min-height:190px" placeholder="Write your message or prepare a starter…"')}<p class="hint">${E(workspace().instructions)}</p>`,'draft',`${btn('Copy text','copy-draft','copy')}${CommunicationsUI.draftAction(a)}<button class="button primary" type="submit">Save draft</button>`,draft?`data-draft-id="${draft.id}"`:'',false,true);}
function prepareDraft(){const form=document.getElementById('modal-form'),a=D.agents.find(a=>a.id===form.elements.agentId.value),channel=form.elements.channel.value;const first=a.name.split(' ')[0],w=workspace();form.elements.body.value=channel==='Phone call'?`Hi ${first}, this is ${w.name} with ${w.company}. Is now a good time for a quick introduction?\n\nAsk about their business, what is working well, and what support would help next.\n\nIf there is interest, agree on a next conversation.`:`Hi ${first}, this is ${w.name} with ${w.company}. I’d love to learn more about your business${a.city?' in '+a.city:''} and introduce myself. Would you be open to a quick conversation next week?`;dirtyForms.add(form);}
function taskDetail(id){
 const t=D.tasks.find(t=>t.id===id);if(!t)throw Error('This task is no longer available.');
 const a=D.agents.find(a=>a.id===t.agentId),draft=t.draftId?D.drafts.find(d=>d.id===t.draftId):null;
 const linkedMessage=t.type==='Message'&&!!t.draftId;
 const matches=linkedMessage&&draft?.agentId===t.agentId&&draft?.channel==='Message'&&draft?.body===t.draftBody;
 const current=matches&&draft.state==='draft',sent=matches&&draft.state==='sent';
 const receipt=sent?(D.communications||[]).find(r=>r.id===draft.communicationId&&r.agentId===t.agentId):null;
 const body=linkedMessage?`<section class="task-message"><h3>${sent?'Saved sent message':'Unsent message draft'}</h3><p class="sub">To ${E(a?.name||'Unknown contact')} · ${E(receipt?.phone||a?.phone||'Phone number missing')}</p>${sent?`<p class="sub">Sent ${E(dateTime(draft.sentAt||draft.sentOn))}</p>`:''}<p class="comm-message">${E(draft?.body||t.draftBody||'Draft unavailable')}</p><p class="hint">${sent?'A confirmed send is saved for this exact message. Review the outcome and complete this task when ready.':current?'Exact draft linked to this task. Review the destination and wording before any send.':'This linked draft changed or is unavailable. Reopen the current draft before acting.'}</p>${!sent&&!CommunicationsUI.allowed(a)?'<p class="comm-notice">Contact source verification is pending, or this contact is in a status that blocks outreach. You can review and copy the draft here; no message is sent.</p>':''}</section>`:`<p style="white-space:pre-wrap;line-height:1.8">${E(t.description||'No description added.')}</p>`;
 const actions=`${a?btn('View contact','task-view-contact','',`data-id="${E(a.id)}"`):''}${linkedMessage&&current?btn('Copy message','task-copy-message','',`data-id="${E(t.id)}"`):''}${linkedMessage&&current&&CommunicationsUI.allowed(a)?btn('Review send in Messages','comm-task-message','',`data-id="${E(t.id)}"`,'soft'):''}${linkedMessage&&current&&CommunicationsUI.allowed(a)&&CommunicationsUI.directSMSAvailable()?btn('Review direct SMS','comm-task-sms','',`data-id="${E(t.id)}"`,'soft'):''}${btn(t.draftId?'Reschedule review':'Edit task','task-edit','',`data-id="${E(id)}"`)}${t.completed?btn('Reopen task','task-reopen','',`data-id="${E(id)}"`):btn('Mark complete','complete-task','check',`data-id="${E(id)}"`,'primary')}`;
 modal(t.title,`<p class="sub">${E(a?.name||'Contact')} · ${E(t.type)} · ${date(t.dueDate)}</p><div class="divider"></div>${body}<div class="details"><div class="detail-pair"><label>Priority</label>${badge(t.priority)}</div><div class="detail-pair"><label>Repeats</label><span>${t.repeatDays?'Every '+t.repeatDays+' days after completion':'Does not repeat'}</span></div></div>`,'',actions);
}
function openGlobal(){modal('Search your workspace',field('Agent, brokerage or city','query','search','','placeholder="Start typing a name…" autocomplete="off"')+'<div class="search-results" id="global-results"></div>');globalResults('');}
function globalResults(q){const items=Model.filter(D.agents,{q}).slice(0,8);document.getElementById('global-results').innerHTML=items.map(a=>`<button class="search-result" data-action="global-profile" data-id="${a.id}">${avatar(a,'tiny')}<span class="grow"><strong>${E(a.name)}</strong><span class="agent-office" style="display:block">${E(a.office)} · ${E(a.city)}</span></span>${icon('right',14)}</button>`).join('')||'<p class="sub">No agents found.</p>';}
async function openProfile(id,retain=false){if(!retain&&!S.profile){S.listScroll=document.getElementById('workspace').scrollTop;S.returnPage=S.page;S.reviewIds=(S.page==='candidates'?visibleAgents():['search','pipeline','liked','watchlist','contacts'].includes(S.page)?visibleAgents():D.agents).map(a=>a.id);}if(!S.reviewIds.includes(id))S.reviewIds.push(id);S.profile=id;S.profileTab='Production';S.period='LTM';S.activityKind='All';await mutate('agent.view',{agentId:id});document.getElementById('workspace').scrollTop=0;}
function alertDefinitions(){modal('Alert definitions',`<p class="sub">Courted-style event categories mapped in the product audit. Sample events exercise these workflows.</p><div class="divider"></div>${[['Newly high potential to move','Move forecast changes to High.'],['Now has no active or pending','No remaining active or pending listings.'],['Lagging / leading the market','Production change compared with similar-tenure peers.'],['No activity / return to activity','A ninety-day period without activity, or the first event afterward.'],['Recent co-broker','A transaction with someone at your office.'],['Highest listing / closing','A new personal price milestone.'],['First listing / closing in zip','Activity in a new area.'],['Open house','A new opportunity to reconnect.']].map(([a,b])=>`<h3 style="margin-top:18px">${a}</h3><p class="sub" style="margin-top:6px">${b}</p>`).join('')}`);}
async function handleAction(b){if(needsOnboarding())return;if(typeof CSVImportUI!=='undefined'&&CSVImportUI.isBusy?.()){toast('Wait for the CSV operation to finish.');return;}if(b.dataset.action?.startsWith('workflow-')){toast('Workflows and sequences are outside the internal pilot.');return;}if(b.dataset.action?.startsWith('perf-'))return PerformanceUI.handleAction(b);if(b.dataset.action?.startsWith('comm-'))return CommunicationsUI.handleAction(b);const ac=b.dataset.action,id=b.dataset.id,v=b.dataset.value;switch(ac){
 case 'navigate':closeModal();navigate(b.dataset.page);break;
 case 'menu':S.menu=S.menu===v?null:v;renderMenu();break;
 case 'category':S.category=v;render();break;
 case 'preferences':preferences();break;
 case 'like':{const a=D.agents.find(a=>a.id===id);await mutate('agent.update',{agentId:id,liked:!a.liked},a.liked?'Removed from liked agents':'Added to liked agents');break;}
 case 'reject-candidate':candidateFeedbackForm(id);break;
 case 'restore-candidate':await mutate('candidate.restore',{agentId:id},'Recommendation restored');break;
 case 'profile':await openProfile(id,!!S.profile);break;
 case 'global-profile':closeModal();await openProfile(id,!!S.profile);break;
 case 'profile-close':S.profile=null;S.page=S.returnPage;render();document.getElementById('workspace').scrollTop=S.listScroll;break;
 case 'profile-prev':case 'profile-next':{const i=S.reviewIds.indexOf(S.profile)+(ac==='profile-next'?1:-1);if(S.reviewIds[i])await openProfile(S.reviewIds[i],true);break;}
 case 'profile-tab':S.profileTab=v;render();break;
 case 'period':if(v==='Custom')modal('Custom date range',field('From','from','date',localDayOffset(-90),'required')+field('To','to','date',D.today,'required'),'custom-period');else{S.period=v;render();}break;
 case 'filters':filterForm();break;
 case 'clear-filters':S.filters={};S.pageNo=1;render();break;
 case 'columns':columnsForm();break;
 case 'column-up':case 'column-down':{const row=b.closest('.column-option');if(ac==='column-up'&&row.previousElementSibling)row.parentElement.insertBefore(row,row.previousElementSibling);else if(ac==='column-down'&&row.nextElementSibling)row.parentElement.insertBefore(row.nextElementSibling,row);break;}
 case 'sort':if(S.sort===b.dataset.key)S.dir*=-1;else{S.sort=b.dataset.key;S.dir=1;}render();break;
 case 'page-size':S.pageSize=Number(v);S.pageNo=1;render();break;
 case 'page-back':S.pageNo--;render();break;
 case 'page-next':S.pageNo++;render();break;
 case 'clear-selection':S.selected.clear();render();break;
 case 'insights':S.insights=!S.insights;render();break;
 case 'stage-filter':S.filters={status:v};navigate('pipeline');break;
 case 'contact':contactForm();break;
 case 'edit-contact':contactForm(id);break;
 case 'note':activityForm('note',id);break;
 case 'interaction':activityForm('interaction',id);break;
 case 'task-create':taskForm(id);break;
 case 'task-bucket':S.taskBucket=v;render();break;
 case 'task-detail':await CommunicationsUI.refreshStatus(false);taskDetail(id);break;
 case 'task-view-contact':closeModal();await openProfile(id);break;

 case 'task-copy-message':{const task=D.tasks.find(t=>t.id===id),draft=D.drafts.find(d=>d.id===task?.draftId);if(!draft||draft.agentId!==task.agentId||draft.channel!=='Message'||draft.state!=='draft'||draft.body!==task.draftBody)throw Error('This task draft changed. Refresh the task before copying.');await native('copy',{text:draft.body});toast('Message copied. Not sent.');break;}
 case 'task-edit':editTask(id);break;
 case 'task-reopen':await mutate('task.reopen',{id},'Task reopened');closeModal();break;
 case 'complete-task':await mutate('task.complete',{id},'Task completed');closeModal();break;
 case 'pin':{const a=D.activities.find(x=>x.id===id);await mutate('activity.pin',{id,pinned:!a.pinned});break;}
 case 'watchlist-create':watchlistForm();break;
 case 'watchlist-edit':watchlistForm(id);break;
 case 'watchlist-open':S.watchlist=id;S.filters={};navigate('watchlist');break;
 case 'add-watchlist':addWatchlist(id);break;
 case 'save-search':modal('Save search',field('Search name','name','text','','required maxlength="100" placeholder="e.g. Austin high potential"')+'<p class="hint">Your current filters will be saved. Results update as local records change.</p>','save-search');break;
 case 'run-search':S.filters={...D.searches.find(s=>s.id===id).filters};navigate('search');break;
 case 'office-search':S.filters={q:v};navigate('search');break;
 case 'draft':draftForm(id);break;
 case 'prepare-draft':prepareDraft();break;
 case 'copy-draft':{const text=document.getElementById('modal-form').elements.body.value;if(!text.trim())throw Error('Write a draft first.');await native('copy',{text});toast('Copied to clipboard. Not sent.');break;}
 case 'dismiss-alert':await mutate('alert.dismiss',{id},'Alert dismissed');break;
 case 'alert-definitions':alertDefinitions();break;
 case 'settings-tab':S.settingsTab=v;render();if(v==='Local data')await refreshRecovery();break;
 case 'history-audit':try{historyAuditState=await native('history.audit');historyAuditError='';}catch(error){historyAuditError=error.message;}render();break;
 case 'recovery-refresh':await refreshRecovery();break;
 case 'recovery-create':{const r=await native('recovery.create');toast(r.verified?'Recovery snapshot created and verified':'Snapshot requested');await refreshRecovery();break;}
 case 'recovery-restore':await native('recovery.restore.pick');break;
 case 'global-search':openGlobal();break;
 case 'notifications':modal('Notifications',empty('You’re all caught up','New follow-up work is available in Tasks. External notifications are not connected.','bell'),'',btn('View tasks','navigate','task','data-page="tasks"'));break;
 case 'export':{const result=await native('export',{text:Model.csv(visibleAgents())});if(!result.cancelled)toast('CSV exported');break;}
 case 'csv-import-pick':await CSVImportUI.pick();break;
 case 'csv-import-review':await CSVImportUI.review();break;
 case 'csv-import-edit':CSVImportUI.edit();break;
 case 'csv-import-commit':await CSVImportUI.commit();break;
 case 'backup':{const result=await native('recovery.create');toast(result.verified?'Recovery snapshot created and verified':'Snapshot requested');await refreshRecovery();break;}
 case 'close-modal':requestCloseModal();break;
 case 'discard-modal':closeModal();break;
 }
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){e.preventDefault();try{await handleAction(b);}catch(error){const out=document.getElementById('form-error');if(out)out.textContent=error.message;else toast(error.message);}}else if(S.menu&&!e.target.closest('.menu')){S.menu=null;renderMenu();}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.dataset.agentField){const payload={agentId:el.dataset.id,[el.dataset.agentField]:el.value};el.disabled=true;await mutate('agent.update',payload,'Saved on this Mac');}
 else if(el.dataset.filter){S.filters[el.dataset.filter]=el.value;S.pageNo=1;render();}
 else if(el.hasAttribute('data-select-all')){const list=visibleAgents().slice((S.pageNo-1)*S.pageSize,S.pageNo*S.pageSize);list.forEach(a=>el.checked?S.selected.add(a.id):S.selected.delete(a.id));render();}
 else if(el.dataset.selectAgent){el.checked?S.selected.add(el.dataset.selectAgent):S.selected.delete(el.dataset.selectAgent);render();}
 else if(el.hasAttribute('data-activity-filter')){S.activityKind=el.value;render();}
 else if(el.hasAttribute('data-comparison')){S.comparison=el.value;render();}
 else if(el.name==='createTask'){document.getElementById('followup-fields').hidden=!el.checked;document.getElementById('f-followTitle').required=el.checked;document.getElementById('f-followDate').required=el.checked;}
 else if(el.name==='agentId'&&el.closest('form')?.dataset.kind==='draft'){const f=el.closest('form');delete f.dataset.draftId;f.elements.body.value='';CommunicationsUI.updateDraftButton(f);}
 else if(el.name==='channel'&&el.closest('form')?.dataset.kind==='draft'){CommunicationsUI.updateDraftButton(el.closest('form'));}
 }catch(error){el.disabled=false;toast(error.message);render();}});
let inputTimer;
document.addEventListener('input',e=>{const el=e.target;if(el.id==='f-query'){globalResults(el.value);return;}if(el.id==='list-query'||el.id==='task-query'){clearTimeout(inputTimer);const value=el.value,pos=el.selectionStart,id=el.id;inputTimer=setTimeout(()=>{if(id==='list-query'){S.filters.q=value;S.pageNo=1;}else S.taskQ=value;render();const next=document.getElementById(id);next?.focus();next?.setSelectionRange(pos,pos);},180);}});
document.addEventListener('input',e=>{const form=e.target.closest?.('form');if(form)dirtyForms.add(form);},true);
document.addEventListener('change',e=>{const form=e.target.closest?.('form');if(form)dirtyForms.add(form);},true);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(needsOnboarding())return;if(document.getElementById('overlay').children.length){toast('Finish or close the current dialog before searching.');return;}openGlobal();}if(e.key==='Escape'){if(document.getElementById('overlay').children.length)requestCloseModal();else{S.menu=null;renderMenu();}}if(e.key==='Tab'&&document.querySelector('.modal')){const nodes=[...document.querySelector('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')].filter(x=>x.offsetParent!==null);if(!nodes.length){e.preventDefault();return;}const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.dataset.kind?.startsWith('workflow-')||form.dataset.kind?.startsWith('perf-')){try{await (form.dataset.kind.startsWith('workflow-')?WorkflowUI:PerformanceUI).handleSubmit(form);}catch(error){toast(error.message);}return;}if(form.id==='communications-test-form'){CommunicationsUI.submitTest(form);return;}if(form.dataset.kind?.startsWith('communications-'))return;if(!form.matches('#modal-form,#settings-form,#context-form,#onboarding-form'))return;const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;const f=new FormData(form),values=Object.fromEntries(f.entries());try{
 if(form.id==='onboarding-form'){await mutate('onboarding.save',values,'Workspace profile saved');return;}
 if(form.id==='context-form'){await mutate('context.save',ContextUI.formToPayload(form),'AI context saved on this Mac');return;}
 if(form.id==='settings-form'){await mutate('settings.save',values,'Settings saved');return;}
 switch(form.dataset.kind){
 case 'candidate-feedback':await mutate('candidate.reject',{agentId:form.dataset.id,reason:values.reason,detail:values.detail||''},'Feedback saved. Candidate removed from recommendations.');break;
 case 'preferences':{const p={cities:f.getAll('cities'),dailyLimit:Number(values.dailyLimit)};for(const key of ['Volume','Units','Price','Years']){p['min'+key]=Number(values['min'+key])||0;p['max'+key]=Number(values['max'+key])||0;p['must'+key]=f.has('must'+key);}await mutate('preferences.save',p,'Preferences saved');break;}
 case 'contact':{
  if(values.linkedinUrl&&!linkedinProfileURL(values.linkedinUrl))throw Error('Enter a LinkedIn profile URL beginning with https://www.linkedin.com/in/.');
  const before=new Set(D.agents.map(a=>a.id)),editing=Boolean(form.dataset.id);
  if(editing)await mutate('agent.update',{...values,agentId:form.dataset.id});else await mutate('agent.create',values);
  const saved=editing?D.agents.find(a=>a.id===form.dataset.id):D.agents.find(a=>!before.has(a.id));
  toast(['needs_review','unverified'].includes(saved?.emailCompanyReview?.state)?'Contact saved. Review the email and brokerage before outreach.':editing?'Contact saved':'Contact added');
  break;
 }
 case 'task-edit':await mutate('task.update',{id:form.dataset.id,...values,...(values.repeatDays!==undefined?{repeatDays:Number(values.repeatDays)}:{})},'Task updated');break;
 case 'task':await mutate('task.create',{...values,repeatDays:Number(values.repeatDays),assignee:workspace().name},'Task created');break;
 case 'activity':{const p={agentId:values.agentId,kind:form.dataset.activity,body:values.body,dateTime:values.dateTime};if(p.kind==='interaction')p.title=values.type+' — '+values.outcome;if(f.has('createTask'))p.task={title:values.followTitle,dueDate:values.followDate};await mutate('activity.create',p,p.kind==='note'?'Note saved':'Interaction recorded');break;}
 case 'filters':if(Number(values.maxVolume)&&Number(values.maxVolume)<Number(values.minVolume))throw Error('Maximum volume must be at least the minimum.');S.filters=values;S.pageNo=1;render();break;
 case 'columns':await mutate('settings.save',{columns:[...form.querySelectorAll('input[name=columns]:checked')].map(c=>c.value)},'Columns updated');break;
 case 'watchlist':await mutate('watchlist.save',{name:values.name,agentIds:f.getAll('agentIds'),...(form.dataset.id?{id:form.dataset.id}:{})},'Watchlist saved');break;
 case 'add-watchlist':{const w=D.watchlists.find(w=>w.id===values.listId),ids=JSON.parse(form.dataset.agentIds);await mutate('watchlist.save',{name:w?.name||values.name,agentIds:[...(w?.agentIds||[]),...ids],...(w?{id:w.id}:{})},'Added to watchlist');break;}
 case 'save-search':await mutate('search.save',{name:values.name,filters:S.filters},'Search saved');break;
 case 'draft':await mutate('draft.save',{agentId:values.agentId,body:values.body,channel:values.channel,...(form.dataset.draftId?{id:form.dataset.draftId}:{})},'Draft saved. Not sent.');break;
 case 'custom-period':if(values.from>values.to)throw Error('The end date must be on or after the start date.');S.custom=values;S.period='Custom';render();break;
 }
 closeModal();
 }catch(error){const out=document.getElementById(form.id==='onboarding-form'?'onboarding-error':form.id==='context-form'?'context-error':form.id==='settings-form'?'settings-error':'form-error');if(out)out.textContent=error.message;else toast(error.message);}finally{if(button)button.disabled=false;}});
CommunicationsUI.bind(render);
WorkflowUI.bind(render);
const sampleProfileView=renderProfile;
renderProfile=function(){const agent=currentAgent();if(agent?.courtedFields){S.profileTab=['Source data','Five-year performance','Activity log'].includes(S.profileTab)?S.profileTab:'Source data';return CSVImportUI.renderProfile(agent);}return sampleProfileView();};
const sampleDashboardView=renderDashboard;
renderDashboard=function(){return D.mode==='mixed'?CSVImportUI.dashboard():sampleDashboardView();};
(async()=>{try{lastDatabaseVersion=(await native('workspace.version')).dataVersion;D=await native('snapshot');shell();render();setInterval(refreshLocalChanges,3000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLocalChanges();});}catch(error){document.getElementById('app').innerHTML=`<div class="boot"><h2>Open Sprout Recruit on your Mac</h2><p>${E(error.message)}</p></div>`;}})();
